    input  x,
    output z
);

    // Internal signals for the three D flip-flops
    reg q0, q1, q2;

    // Complemented outputs for the AND and OR gates
    wire q0_n, q1_n, q2_n;

    // Assign complemented signals
    assign q0_n = ~q0;
    assign q1_n = ~q1;
    assign q2_n = ~q2;

    // D Flip-Flops with synchronous reset (initial value 0)
    always @(posedge clk) begin
        // The D input for each flip-flop is the XOR of x and its own output (q)
        q0 <= x ^ q0;
        q1 <= x ^ q1;
        q2 <= x ^ q2;
    end

    // Three-input NOR gate
