    wire x3 = x[3];
    wire x2 = x[2];
    wire x1 = x[1];
    wire x0 = x[0];

    // K-map derived expression:
    // f = x3'&x2'&x1&x0'   (m1)
    //    | x3'&x2&x1&x0     (m5)
    //    | x3&x2&x1'&x0'    (m12)
    //    | x3&x2&x1&x0'     (m13)
    //    | x3&x2'&x1&x0'    (m8)
    //    | x3&x2'&x1'&x0    (m10)
    //    | x3&x2&x1         (covering m12, m13, m14, m15)
    //    | x3&x2'&x1'       (covering m8, m10)
    //    | x2&x1'&x0'       (covering m0, m2 with don't-cares, but m0 is d, m2 is 0 so not used)
    //    | x2&x1            (covering m5, m7(d), m13, m15)
    //    | x2'&x1           (covering m1, m3(d))
    //    | x1&x0'           (covering m4(d), m12, m13)
    //    | x1'&x0           (covering m2(d), m10)
    //    | x0'              (covering m0(d), m4(d), m8, m12)
    //
    // After prime implicant chart minimization:
    // f = x3&x2 | x3&x1 | x2&x1 | x1&x0' | x0'
    // Further simplification using don't-cares yields:
    // f = x3&x2 | x3&x1 | x2&x1 | x0'

    assign f = (x3 & x2) |
               (x3 & x1) |
               (x2 & x1) |
               (~x0);

endmodule

