module TopModule (
    input  clk,
    input  L,
    input  q_in,
    input  r_in,
    output Q
);

    // Internal signal to hold the 3-bit state (q[2:0])
    reg [2:0] q_reg;

    // Sequential logic: D flip-flop behavior with load and shift
    always @(posedge clk) begin
        if (L) begin
            // Load mode: shift in r_in as the new MSB (q[2])
            q_reg <= {r_in, q_reg[1:0]};
        end else begin
            // Shift mode: shift right, XOR feedback from q[2] into q[0]
            // New q[0] = q[1] XOR q[2]
            // New q[1] = q[0] (old)
            // New q[2] = q[2] (old, retained through shift)
            q_reg <= {q_reg[1] ^ q_reg[2], q_reg[0], q_reg[2]};
        end
    end

    // Output assignment: map the internal MSB (q[2]) to the top-level Q port
    assign Q = q_reg[2];

endmodule

