module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    state_t state, next_state;

    // Datapath registers to hold the 3 bytes of the current message
    logic [7:0] byte1, byte2, byte3;

    // FSM state transition logic (positive edge triggered, async reset)
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= IDLE;
            byte1     <= 8'b0;
            byte2     <= 8'b0;
            byte3     <= 8'b0;
            done      <= 1'b0;
        end else begin
            state     <= next_state;
            done      <= 1'b0; // default: de-assert done

            case (state)
                IDLE: begin
                    // Discard bytes until in[3] is 1
                    if (in[3]) begin
                        next_state <= BYTE1;
                        byte1      <= in;
                    end else begin
                        next_state <= IDLE;
                    end
                end

                BYTE1: begin
                    // Receive second byte
                    next_state <= BYTE2;
                    byte2      <= in;
                end

                BYTE2: begin
                    // Receive third byte
                    next_state <= BYTE3;
                    byte3      <= in;
                end

                BYTE3: begin
                    // All 3 bytes received; assert done in the next cycle
                    // out_bytes is updated with the assembled message
                    out_bytes <= {byte1, byte2, byte3};
                    next_state <= IDLE;
                    done       <= 1'b1;
                end
            endcase
        end
    end

endmodule

