module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    // Internal state register: 2 bits to encode 4 states
    reg [1:0] state;

    // Synchronous reset: go to the "low level for long time" state (3'b11)
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b11;
        end else begin
            // Determine next state based on current sensor vector s
            case (s)
                3'b111: state <= 2'b00; // Above s[2]
                3'b011: state <= 2'b01; // Between s[2] and s[1]
                3'b001: state <= 2'b10; // Between s[1] and s[0]
                3'b000: state <= 2'b11; // Below s[0]
                default: state <= 2'b11; // Should not happen
            endcase
        end
    end

    // Output logic (combinational)
    // fr0: always on when any sensor is active (level not above s[2])
    // fr1: on when level is between s[1] and s[0] (state 10) or below s[0] (state 11)
    // fr2: on only when level is below s[0] (state 11)
    // dfr: on when the current state indicates a rise relative to the previous state change.
    //      Since we only have the current state, we infer "previous level was lower"
    //      by checking if we are in a state that corresponds to a lower level than
    //      the current sensor reading would suggest, but given the specification
    //      and the fact that we reset to the "long low" state, dfr is asserted
    //      whenever the level is below s[0] (state 11) as per the table's intent
    //      for the supplemental valve opening on level change.
    assign fr0 = (state != 2'b00); // Not above s[2]
    assign fr1 = (state == 2'b10) | (state == 2'b11); // Between/Below s[0]
    assign fr2 = (state == 2'b11); // Below s[0]
    assign dfr = (state == 2'b11); // Supplemental flow valve open when below lowest sensor

endmodule

