module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // State encoding
    typedef enum logic [2:0] {
        STATE_A   = 3'b000,
        STATE_B   = 3'b001,
        STATE_C   = 3'b010,
        STATE_D   = 3'b011,
        STATE_E   = 3'b100
    } state_t;

    state_t state, next_state;

    // Outputs (combinational logic)
    assign f = (state == STATE_A) ? 1'b0 : 1'b1;
    assign g = (state == STATE_D) ? 1'b1 : 1'b0;

    // State register (positive edge triggered, synchronous active-low reset)
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= STATE_A;
        end else begin
            state <= next_state;
        end
    end

    // Next-state logic (combinational)
    always_comb begin
        // Default: stay in current state
        next_state = state;

        case (state)
            STATE_A: begin
                // On de-assertion of reset, go to STATE_B and assert f for one cycle
                if (!resetn) begin
                    next_state = STATE_B;
                end
            end

            STATE_B: begin
                // After entering STATE_B, f is already asserted for one cycle.
                // Transition to STATE_C to start monitoring x.
                next_state = STATE_C;
            end

            STATE_C: begin
                // Monitor x for the sequence 1, 0, 1 over three successive cycles.
                // If the sequence is detected, go to STATE_D.
                if (seq_101) begin
                    next_state = STATE_D;
                end
            end

            STATE_D: begin
                // While in STATE_D, g is asserted.
                // Monitor y: if y becomes 1 within two clock cycles, stay in STATE_D (g stays 1).
                // If y does not become 1 within two cycles, go to STATE_E (g=0).
                if (y == 1'b1) begin
                    // y became 1 within the allowed window -> stay in STATE_D
                    next_state = STATE_D;
                end else if (wait_cnt == 2'b10) begin
                    // Two cycles have passed without y=1 -> go to STATE_E (g=0)
                    next_state = STATE_E;
                end else begin
                    next_state = STATE_D;
                end
            end

            STATE_E: begin
                // g = 0 permanently until reset
                next_state = STATE_E;
            end

            default: next_state = state;
        endcase
    end

    // Registers for monitoring x history (to detect 1,0,1 sequence)
    reg x1, x2; // x1 = previous x, x2 = x before previous

    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            x1 <= 1'b0;
            x2 <= 1'b0;
        end else begin
            x2 <= x1;
            x1 <= x;
        end
    end

    // Wire for sequence detection in STATE_C
    wire seq_101;
    assign seq_101 = (x == 1'b1) && (x1 == 1'b0) && (x2 == 1'b1);

    // Registers for y monitoring and two-cycle timeout in STATE_D
    reg y1, y2; // y1 = previous y, y2 = y before previous
    reg [1:0] wait_cnt; // counter for cycles without y=1

    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            y1 <= 1'b0;
            y2 <= 1'b0;
            wait_cnt <= 2'b00;
        end else begin
            y2 <= y1;
            y1 <= y;
            // Simple counter: increment if y is not 1, else reset
            if (y == 1'b1) begin
                wait_cnt <= 2'b00;
            end else begin
                wait_cnt <= wait_cnt + 1'b1;
            end
        end
    end

endmodule

