module TopModule (
    input  d,
    input  done_counting,
    input  ack,
    input  state [9:0],
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

    // Internal wires for decoded state signals
    wire S_state, S1_state, S11_state, S110_state, B0_state, B1_state, B2_state, B3_state, Count_state, Wait_state;

    // One-hot decoding
    assign S_state   = state[0];
    assign S1_state  = state[1];
    assign S11_state = state[2];
    assign S110_state= state[3];
    assign B0_state  = state[4];
    assign B1_state  = state[5];
    assign B2_state  = state[6];
    assign B3_state  = state[7];
    assign Count_state= state[8];
    assign Wait_state= state[9];

    // ============================================
    // Next-state logic (one-hot generation)
    // ============================================

    // S_next: next state is S
    // From S: d=0 -> S; from S1: d=0 -> S; from S110: d=0 -> S; from Wait: ack=1 -> S
    assign S_next = (~d & S_state) |
                    (~d & S1_state) |
                    (~d & S110_state) |
                    (ack & Wait_state);

    // S1_next: next state is S1
    // From S: d=1 -> S1
    assign S1_next = (d & S_state);

    // Count_next: next state is Count
    // From B3: always -> Count
    assign Count_next = B3_state;

    // Wait_next: next state is Wait
    // From Count: done_counting=1 -> Wait
    assign Wait_next = (done_counting & Count_state);

    // B3_next: next state is B3
    // From B2: always -> B3
    assign B3_next = B2_state;

    // ============================================
    // Output logic
    // ============================================

    // done: Output logic
    // Wait state has done=1
    assign done = Wait_state;

    // counting: Output logic
    // Count state has counting=1
    assign counting = Count_state;

    // shift_ena: Output logic
    // B0, B1, B2, B3 have shift_ena=1
    assign shift_ena = B0_state | B1_state | B2_state | B3_state;

endmodule

