module TopModule (
    input  clk,
    input  reset,
    input  slowena,
    output q
);

    // q is a 4-bit output representing the counter value
    output [3:0] q;

    // Internal register to hold the counter value
    reg [3:0] count;

    // Synchronous always block triggered on the positive edge of clk
    always @(posedge clk) begin
        if (reset) begin
            // Active high synchronous reset: set counter to 0
            count <= 4'b0000;
        end else if (slowena) begin
            // Increment counter only if slowena is high and not resetting
            // Natural binary wrap-around from 9 (1001) to 0 (0000)
            count <= count + 1;
        end
        // If slowena is low, count retains its current value (hold/pause)
    end

    // Continuous assignment to output the counter value
    assign q = count;

endmodule

