module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic bump_left,
    input  logic bump_right,
    input  logic ground,
    input  logic dig,
    output logic walk_left,
    output logic walk_right,
    output logic aaah,
    output logic digging
);

    // State encoding
    typedef enum logic [2:0] {
        S_WALK_LEFT,    // 3'b000
        S_WALK_RIGHT,   // 3'b001
        S_FALLING,      // 3'b010
        S_DIGGING,      // 3'b011
        S_SPLATTERED    // 3'b100
    } state_t;

    state_t state, next_state;

    // Outputs (Moore)
    assign walk_left   = (state == S_WALK_LEFT);
    assign walk_right  = (state == S_WALK_RIGHT);
    assign aaah        = (state == S_FALLING);
    assign digging     = (state == S_DIGGING);

    // State register
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= S_WALK_LEFT;
        end else begin
            state <= next_state;
        end
    end

    // Registers for fall duration and direction memory
    logic [4:0] fall_cnt; // counts 0 to 31 (more than enough for >20)
    logic [1:0] walk_dir; // 0 = left, 1 = right. Stores direction before fall.

    // Counter and direction update logic
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            fall_cnt <= 0;
            walk_dir <= 0;
        end else begin
            case (state)
                S_WALK_LEFT, S_WALK_RIGHT: begin
                    // Walking: reset fall counter, store current direction
                    fall_cnt <= 0;
                    if (state == S_WALK_LEFT)
                        walk_dir <= 0;
                    else
                        walk_dir <= 1;
                end
                S_DIGGING: begin
                    // Digging on ground: reset fall counter
                    fall_cnt <= 0;
                    // walk_dir preserved (set when entering dig from walking)
                end
                S_FALLING: begin
                    // While falling: increment counter, but cap it
                    if (fall_cnt < 31)
                        fall_cnt <= fall_cnt + 1;
                    // walk_dir is preserved from before the fall
                end
                S_SPLATTERED: begin
                    // Keep counter and direction, but state doesn't change usefully
                end
                default: begin
                    fall_cnt <= 0;
                    walk_dir <= 0;
                end
            endcase
        end
    end

    // Next-state logic (combinational)
    always_comb begin
        // Default: stay in current state
        next_state = state;

        case (state)
            S_WALK_LEFT: begin
                // Priority: fall > dig > switch direction
                if (!ground) begin
                    // Fall immediately when ground disappears
                    next_state = S_FALLING;
                end else if (dig) begin
                    // Start digging
                    next_state = S_DIGGING;
                end else if (bump_left || bump_right) begin
                    // Switch direction: bump_left -> walk right, bump_right -> walk left
                    // If both bumped, bump_left takes precedence in the expression below.
                    next_state = (bump_left) ? S_WALK_RIGHT : S_WALK_LEFT;
                end
            end

            S_WALK_RIGHT: begin
                if (!ground) begin
                    next_state = S_FALLING;
                end else if (dig) begin
                    next_state = S_DIGGING;
                end else if (bump_left || bump_right) begin
                    next_state = (bump_right) ? S_WALK_LEFT : S_WALK_RIGHT;
                end
            end

            S_FALLING: begin
                if (ground) begin
                    // Ground reappeared
                    if (fall_cnt > 20) begin
                        // Splatter: fell for more than 20 cycles
                        next_state = S_SPLATTERED;
                    end else begin
                        // Resume walking in the same direction as before the fall
                        if (walk_dir == 0)
                            next_state = S_WALK_LEFT;
                        else
                            next_state = S_WALK_RIGHT;
                    end
                end else begin
                    // Ground still 0, keep falling
                    // No transition, stay in S_FALLING
                end
            end

            S_DIGGING: begin
                if (!ground) begin
                    // Reached the other side (ground disappeared while digging)
                    // Fall down
                    next_state = S_FALLING;
                end else if (bump_left || bump_right) begin
                    // Being bumped while digging has no effect
                    // stay in S_DIGGING (default next_state)
                end else begin
                    // Continue digging
                end
            end

            S_SPLATTERED: begin
                // Forever stuck, no transitions
                // next_state remains S_SPLATTERED (default)
            end
        endcase
    end

    // Output assignments are Moore, done above.

endmodule
